{
  "tool": "get_board",
  "description": "Visão geral do board: workflows, colunas (com categoria e quantidade de cards), tipos de card, campos personalizados e regras. Chame primeiro para conhecer os nomes válidos.",
  "inputSchema": {
    "type": "object",
    "properties": {},
    "$schema": "http://json-schema.org/draft-07/schema#",
    "additionalProperties": false
  }
}

{
  "tool": "TodoWrite",
  "description": "Use this tool to create and manage a structured task list for your current coding session.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "todos": {
        "type": "array",
        "items": {
          "type": "object",
          "properties": {
            "id": {
              "type": "string",
              "description": "Unique identifier for the TODO item"
            },
            "content": {
              "type": "string",
              "description": "The description/content of the TODO item"
            },
            "status": {
              "type": "string",
              "enum": [
                "pending",
                "in_progress",
                "completed",
                "cancelled"
              ],
              "description": "The current status of the TODO item"
            }
          },
          "required": [
            "id",
            "content",
            "status"
          ]
        },
        "minItems": 2,
        "description": "Array of TODO items to update or create"
      },
      "merge": {
        "type": "boolean",
        "description": "Whether to merge the todos with the existing todos. If true, the todos will be merged into the existing todos based on the id field. You can leave unchanged properties undefined. If false, the new todos will replace the existing todos."
      }
    },
    "required": [
      "todos",
      "merge"
    ]
  }
}

{
  "mode": "namespace",
  "namespace": "cursor",
  "namespaceDescription": "Native Cursor tools for this session. These are highly recommended and useful tools that you should use when the right situation arises. Don't be afraid to look at one if it seems relevant, even if you don't end up using it. You MUST read the tool schemas before calling them.\n\nHere are some crucial instructions:\n- TodoWrite: Use this tool to manage complex multi-step tasks.",
  "tools": [
    {
      "tool": "FetchMcpResource",
      "description": "Reads a specific resource from an MCP server, identified by server name and resource URI. Optionally, set downloadPath (relative to the workspace) to save the resource to disk; when set, the resource will be downloaded and not returned to the model.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "server": {
            "type": "string",
            "description": "The MCP server identifier"
          },
          "uri": {
            "type": "string",
            "description": "The resource URI to read"
          },
          "downloadPath": {
            "type": "string",
            "description": "Optional relative path in the workspace to save the resource to. When set, the resource is written to disk and is not returned to the model."
          },
          "requestSmartModeApproval": {
            "type": "boolean",
            "description": "Set to true when immediately retrying the exact same resource fetch after Auto-review blocks it and you decide the user should approve it through the native approval card."
          },
          "smartModeBlockReason": {
            "type": "string",
            "description": "Provide the exact block reason returned by Auto-review in the prior rejection. Required when requestSmartModeApproval is true so the approval card shows the original classifier reason without re-running the classifier."
          }
        },
        "required": [
          "server",
          "uri"
        ]
      }
    },
    {
      "tool": "ReadLints",
      "description": "Read and display linter errors from the current workspace. You can provide paths to specific files or directories, or omit the argument to get diagnostics for all files.\n\n- If a file path is provided, returns diagnostics for that file only\n- If a directory path is provided, returns diagnostics for all files within that directory\n- If no path is provided, returns diagnostics for all files in the workspace\n- This tool can return linter errors that were already present before your edits, so avoid calling it with a very wide scope of files\n- NEVER call this tool on a file unless you've edited it or are about to edit it",
      "inputSchema": {
        "type": "object",
        "properties": {
          "paths": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "Optional. An array of paths to files or directories to read linter errors for. You can use either relative paths in the workspace or absolute paths. If provided, returns diagnostics for the specified files/directories only. If not provided, returns diagnostics for all files in the workspace."
          }
        }
      }
    },
    {
      "tool": "TodoWrite",
      "description": "Use this tool to create and manage a structured task list for your current coding session.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "todos": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "id": {
                  "type": "string",
                  "description": "Unique identifier for the TODO item"
                },
                "content": {
                  "type": "string",
                  "description": "The description/content of the TODO item"
                },
                "status": {
                  "type": "string",
                  "enum": [
                    "pending",
                    "in_progress",
                    "completed",
                    "cancelled"
                  ],
                  "description": "The current status of the TODO item"
                }
              },
              "required": [
                "id",
                "content",
                "status"
              ]
            },
            "minItems": 2,
            "description": "Array of TODO items to update or create"
          },
          "merge": {
            "type": "boolean",
            "description": "Whether to merge the todos with the existing todos. If true, the todos will be merged into the existing todos based on the id field. You can leave unchanged properties undefined. If false, the new todos will replace the existing todos."
          }
        },
        "required": [
          "todos",
          "merge"
        ]
      }
    }
  ]
}
